'use client';

import { useEffect, useRef, useState } from 'react';
import { Download, Loader2 } from 'lucide-react';

import DashboardHeader from '@/components/DashboardHeader';
import AssessmentSidebar from '@/components/AssessmentSidebar';
import CompanyMatchCarousel from '@/components/CompanyMatchCarousel';
import KeyStrengths from '@/components/KeyStrengths';
import SmartSuggestions from '@/components/SmartSuggestions';
import KeywordSkillOptimization from '@/components/KeywordSkillOptimization';
import FormattingReadability from '@/components/FormattingReadability';
import type { AnalysisResult } from '@/types/analysis';
import { getStoredUser } from '@/lib/auth';
import { generateReportPDF } from '@/lib/exportReport';

export default function DashboardPage() {
  const [result, setResult] = useState<AnalysisResult | null>(null);
  const [notFound, setNotFound] = useState(false);
  const [isExporting, setIsExporting] = useState(false);
  const loaded = useRef(false);

  const handleExport = async () => {
    if (isExporting || !result) return;
    setIsExporting(true);
    try {
      generateReportPDF(result, getStoredUser());
    } catch (err) {
      console.error('Failed to generate report PDF:', err);
    } finally {
      setIsExporting(false);
    }
  };

  useEffect(() => {
    // Guard against React Strict Mode double-invocation.
    if (loaded.current) return;
    loaded.current = true;

    const raw = sessionStorage.getItem('aura_result');
    if (!raw) {
      setNotFound(true);
      return;
    }

    try {
      const parsed = JSON.parse(raw) as AnalysisResult;
      setResult(parsed);

      // Keep src 1 behavior: consume the one-time analysis result only
      // after a successful parse.
      sessionStorage.removeItem('aura_result');
    } catch {
      setNotFound(true);
    }
  }, []);

  if (notFound) {
    return (
      <div className="relative flex min-h-screen items-center justify-center overflow-hidden bg-[#f0eeff] px-4">
        <div className="pointer-events-none absolute -left-32 top-20 size-[420px] rounded-full bg-violet-400/25 blur-[120px]" />
        <div className="pointer-events-none absolute -right-32 bottom-10 size-[420px] rounded-full bg-cyan-400/20 blur-[120px]" />

        <div className="relative z-10 w-full max-w-md rounded-3xl border-[1.5px] border-white bg-white/72 p-8 text-center shadow-[0px_10px_30px_0px_rgba(17,24,39,0.06)] backdrop-blur-[12px]">
          <p className="mb-5 text-lg font-semibold text-[#4b5563]">No analysis found.</p>
          <a
            href="/upload"
            className="inline-flex rounded-full bg-gradient-to-r from-[#7c3aed] via-[#a78bfa] to-[#06b6d4] px-6 py-3 font-bold text-white shadow-[0px_8px_12px_rgba(124,58,237,0.2)] transition hover:brightness-105"
          >
            Upload a Resume
          </a>
        </div>
      </div>
    );
  }

  if (!result) {
    return (
      <div className="relative flex min-h-screen items-center justify-center overflow-hidden bg-[#f0eeff]">
        <div className="pointer-events-none absolute left-1/2 top-1/3 size-[420px] -translate-x-1/2 rounded-full bg-violet-400/20 blur-[120px]" />
        <p className="relative z-10 text-sm font-medium text-[#4b5563]">Loading analysis…</p>
      </div>
    );
  }

  return (
    <div className="relative min-h-screen w-full overflow-hidden bg-[#f0eeff] font-['DM_Sans',sans-serif] px-4 pb-20 pt-20 sm:px-8 lg:px-20">
      {/* Ambient background orbs, matched to the Aura Figma frame */}
      <div className="pointer-events-none absolute -left-[100px] top-[-40px] size-[500px] rounded-full bg-violet-500/20 blur-[110px]" />
      <div className="pointer-events-none absolute -right-[150px] top-[130px] size-[550px] rounded-full bg-cyan-400/15 blur-[120px]" />
      <div className="pointer-events-none absolute left-[35%] top-[500px] size-[450px] rounded-full bg-fuchsia-400/10 blur-[110px]" />
      <div className="pointer-events-none absolute -right-[120px] top-[1000px] size-[500px] rounded-full bg-violet-500/15 blur-[120px]" />
      <div className="pointer-events-none absolute -left-[120px] top-[1500px] size-[480px] rounded-full bg-cyan-400/15 blur-[115px]" />

      {/* Top accent line, as in the Figma frame */}
      <div className="pointer-events-none absolute inset-x-0 top-0 h-[3px] bg-gradient-to-r from-[#8b5cf6] via-[#06b6d4] to-transparent" />

      <div className="relative z-10 mx-auto max-w-7xl">
        <DashboardHeader result={result} />

        {/* Welcome row, with a working Export PDF button (moved here from DashboardHeader,
            same generateReportPDF/getStoredUser logic, same isExporting state). */}
        <div className="mb-8 flex items-center justify-between gap-4">
          <div>
            <h1 className="text-[28px] font-extrabold text-[#111827]">
              Welcome back
            </h1>
            <p className="mt-1 text-sm text-[#4b5563]">
              Here is your latest resume optimization progress dashboard.
            </p>
          </div>
          <button
            type="button"
            onClick={handleExport}
            disabled={isExporting}
            className="flex shrink-0 items-center gap-2 rounded-xl border-[1.5px] border-[#e3e5eb] bg-white/72 px-5 py-3 text-sm font-medium text-[#454a54] shadow-[0px_2px_8px_0px_rgba(0,0,0,0.05)] backdrop-blur-[12px] transition-colors hover:bg-white disabled:cursor-not-allowed disabled:opacity-60"
          >
            {isExporting ? (
              <Loader2 className="size-[18px] animate-spin" />
            ) : (
              <Download className="size-[18px]" />
            )}
            {isExporting ? 'Exporting…' : 'Export PDF'}
          </button>
        </div>

        {/* Analysis context / keyword strip, restyled for the light Aura theme */}
        <div className="mb-6 flex flex-wrap items-center gap-2">
          {result.keywords.map((kw) => (
            <span
              key={kw}
              className="rounded-full border border-violet-500/20 bg-violet-500/10 px-3 py-1 text-xs font-bold text-violet-600"
            >
              {kw}
            </span>
          ))}
          <span className="rounded-full border-[1.5px] border-white bg-white/72 px-3 py-1 text-xs font-bold text-[#4b5563]">
            {result.total_jobs} jobs found
          </span>
        </div>

        {/* Upload Resume card + sidebar row, matching the Figma upload-section-card + sidebar layout.
            NOTE: this card is presentational only — your /dashboard route doesn't currently have
            upload-handling logic (that lives on /upload). Wire the inputs/button to your real
            handler, or tell me the function name and I'll connect it. */}
        <div className="mb-6 flex flex-col gap-8 lg:flex-row lg:items-stretch">
          <div className="flex-1 rounded-3xl border-[1.5px] border-white bg-white/72 p-7 shadow-[0px_15px_40px_0px_rgba(17,24,39,0.04)] backdrop-blur-[12px]">
            <div className="mb-6">
              <h2 className="text-xl font-extrabold text-[#111827]">Upload Resume</h2>
              <p className="mt-1 text-sm text-[#4b5563]">
                Instantly optimize your resume against Applicant Tracking Systems (ATS) and target
                benchmarks.
              </p>
            </div>

            <div className="flex flex-col items-center justify-center gap-3 rounded-2xl border-[1.5px] border-dashed border-[#7c3aed] bg-white/60 py-10 text-center">
              <div className="flex size-12 items-center justify-center rounded-3xl bg-violet-500/[0.06]">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#7c3aed" strokeWidth="2">
                  <path
                    d="M12 16V8m0 0l-3.5 3.5M12 8l3.5 3.5M6 20h12a2 2 0 002-2v-1a5 5 0 00-4.5-4.975A5.5 5.5 0 007 14.055 4 4 0 004 18a2 2 0 002 2z"
                    strokeLinecap="round"
                    strokeLinejoin="round"
                  />
                </svg>
              </div>
              <div>
                <p className="text-sm font-semibold text-[#111827]">
                  Drag and drop your resume here
                </p>
                <p className="text-[13px] text-[#4b5563]">
                  or <span className="font-semibold text-[#7c3aed]">click to browse</span>
                </p>
              </div>
              <p className="text-[11px] text-[#9ca3af]">PDF, DOCX up to 10MB</p>
            </div>

            <div className="mt-5 flex flex-col gap-4">
              <div className="flex flex-col gap-4 sm:flex-row">
                <label className="flex-1">
                  <span className="mb-1.5 block text-[13px] font-semibold text-[#4b5563]">
                    Target Job Title
                  </span>
                  <input
                    type="text"
                    placeholder="e.g. Senior Product Designer"
                    className="w-full rounded-[10px] border border-[#e5e7eb] bg-white px-3.5 py-3 text-sm text-[#111827] placeholder:text-[#9ca3af] shadow-[0px_1px_1.5px_rgba(17,24,39,0.04)] focus:outline-none focus:ring-2 focus:ring-violet-300"
                  />
                </label>
                <label className="flex-1">
                  <span className="mb-1.5 block text-[13px] font-semibold text-[#4b5563]">
                    Target Companies
                  </span>
                  <input
                    type="text"
                    placeholder="e.g. Google, Apple, Meta"
                    className="w-full rounded-[10px] border border-[#e5e7eb] bg-white px-3.5 py-3 text-sm text-[#111827] placeholder:text-[#9ca3af] shadow-[0px_1px_1.5px_rgba(17,24,39,0.04)] focus:outline-none focus:ring-2 focus:ring-violet-300"
                  />
                </label>
              </div>
              <button
                type="button"
                className="w-full rounded-full bg-gradient-to-r from-[#7c3aed] via-[#a78bfa] to-[#06b6d4] py-3.5 text-[15px] font-bold text-white shadow-[0px_8px_12px_rgba(124,58,237,0.2)] transition hover:brightness-105"
              >
                Upload &amp; Analyze
              </button>
            </div>
          </div>

          {/* Left sidebar */}
          <div className="w-full shrink-0 lg:w-[420px]">
            <AssessmentSidebar
              score={result.ats_score}
              sections={result.sections}
            />
          </div>
        </div>

        {/* Stat tiles, matching the Figma stats-row.
            "Jobs Targeted" uses your real result.total_jobs. "Resumes Uploaded" and "Match Score"
            have no backing field on AnalysisResult yet — placeholders below, swap in real data
            or tell me the field names. */}
        <div className="mb-6 grid grid-cols-1 gap-6 sm:grid-cols-3">
          <div className="rounded-[20px] border-[1.5px] border-white bg-white/72 p-6 shadow-[0px_10px_30px_0px_rgba(17,24,39,0.03)] backdrop-blur-[12px]">
            <p className="text-sm font-semibold text-[#4b5563]">Resumes Uploaded</p>
            <div className="mt-2 flex items-baseline justify-between">
              <p className="text-4xl font-extrabold text-[#111827]">—</p>
              <span className="rounded-full bg-[#ecfdf5] px-2 py-1 text-xs font-bold text-[#10b981]">
                placeholder
              </span>
            </div>
          </div>
          <div className="rounded-[20px] border-[1.5px] border-white bg-white/72 p-6 shadow-[0px_10px_30px_0px_rgba(17,24,39,0.03)] backdrop-blur-[12px]">
            <p className="text-sm font-semibold text-[#4b5563]">Jobs Targeted</p>
            <div className="mt-2 flex items-baseline justify-between">
              <p className="text-4xl font-extrabold text-[#111827]">{result.total_jobs}</p>
            </div>
          </div>
          <div className="rounded-[20px] border-[1.5px] border-white bg-white/72 p-6 shadow-[0px_10px_30px_0px_rgba(17,24,39,0.03)] backdrop-blur-[12px]">
            <p className="text-sm font-semibold text-[#4b5563]">Match Score</p>
            <div className="mt-2 flex items-baseline justify-between">
              <p className="text-4xl font-extrabold text-[#111827]">{result.ats_score}%</p>
              <span className="rounded-full bg-[#ecfdf5] px-2 py-1 text-xs font-bold text-[#10b981]">
                using ats_score
              </span>
            </div>
          </div>
        </div>

        <div className="flex flex-col gap-6">
          {/* Main dashboard content */}
          <div className="min-w-0 flex-1 space-y-6">
            <CompanyMatchCarousel companies={result.companies} />

            <KeywordSkillOptimization skillGaps={result.skill_gaps} />

            <FormattingReadability grammarIssues={result.grammar_issues} />

            <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
              <KeyStrengths strengths={result.strengths} />
              <SmartSuggestions improvements={result.improvements} />
            </div>

            {/* Top Job Matches — same data/functionality as before, restyled to the Aura light-glass look */}
            <div className="rounded-3xl border-[1.5px] border-white bg-white/72 p-8 shadow-[0px_10px_30px_0px_rgba(17,24,39,0.03)] backdrop-blur-[12px]">
              <div className="mb-5 flex items-end justify-between gap-4">
                <div>
                  <h2 className="text-lg font-bold text-[#111827]">Top Job Matches</h2>
                  <p className="mt-1 text-[13px] text-[#4b5563]">
                    Roles with the strongest match to your resume
                  </p>
                </div>
              </div>

              <div className="space-y-3">
                {result.top_jobs.map((job, i) => (
                  <a
                    key={`${job.title}-${job.company}-${i}`}
                    href={job.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="group block rounded-2xl border-[1.5px] border-white bg-white/72 p-4 shadow-[0px_10px_30px_0px_rgba(17,24,39,0.03)] transition-all hover:border-violet-500/30 hover:bg-violet-500/[0.04]"
                  >
                    <div className="flex items-start justify-between gap-4">
                      <div className="min-w-0 flex-1">
                        <p className="truncate font-bold text-[#111827] group-hover:text-violet-700">
                          {job.title}
                        </p>
                        <p className="mt-1 text-sm text-[#4b5563]">
                          {job.company} · {job.location}
                        </p>
                        <p className="mt-1 line-clamp-2 text-xs leading-relaxed text-[#9ca3af]">
                          {job.description}
                        </p>

                        {job.matched_skills.length > 0 && (
                          <div className="mt-2 flex flex-wrap gap-1">
                            {job.matched_skills.slice(0, 4).map((skill, skillIndex) => (
                              <span
                                key={`${skill}-${skillIndex}`}
                                className="rounded-md border border-emerald-500/20 bg-emerald-50 px-2 py-0.5 text-[10px] font-bold text-emerald-600"
                              >
                                {skill}
                              </span>
                            ))}
                          </div>
                        )}
                      </div>

                      <div className="shrink-0 text-right">
                        <span className="bg-gradient-to-r from-[#8b5cf6] to-[#06b6d4] bg-clip-text text-lg font-black text-transparent">
                          {job.total_score}
                        </span>
                        <p className="text-[10px] font-bold uppercase tracking-wider text-[#9ca3af]">
                          Score
                        </p>
                      </div>
                    </div>
                  </a>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Footer, matching the Figma footer-wrapper */}
      <div className="relative z-10 mx-auto mt-16 max-w-7xl">
        <div
          className="h-px w-full"
          style={{
            backgroundImage:
              'linear-gradient(90deg, rgba(139,92,246,0) 0%, rgba(139,92,246,0.19) 30%, rgba(6,182,212,0.19) 70%, rgba(6,182,212,0) 100%)',
          }}
        />
        <div className="flex items-center justify-between bg-white/40 px-2 py-6 text-[13px]">
          <p className="text-[#9ca3af]">© 2026 Aura. All rights reserved.</p>
          <div className="flex gap-8 font-medium text-[#4b5563]">
            <span>Privacy Policy</span>
            <span>Terms of Service</span>
          </div>
        </div>
      </div>
    </div>
  );
}